import httpx, sys

def check(base: str = "{{base_url}}") -> bool:
    try:
        r = httpx.get(f"{base}/v1/models", timeout=5)
        return r.status_code == 200
    except httpx.HTTPError:
        return False

if __name__ == "__main__":
    ok = check()
    print("ok" if ok else "down")
    sys.exit(0 if ok else 1)
